package com.ipssaludvital.app;
import android.os.Bundle;import android.content.Intent;import android.graphics.Typeface;import android.view.ViewGroup;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;import org.json.JSONArray;import org.json.JSONObject;
public class DashboardActivity extends AppCompatActivity{
 ApiClient api=new ApiClient();LinearLayout container;TextView welcome,countA,countN;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_dashboard);welcome=findViewById(R.id.txtWelcome);countA=findViewById(R.id.txtAppointments);countN=findViewById(R.id.txtNotifications);container=findViewById(R.id.appointmentsContainer);findViewById(R.id.btnLogout).setOnClickListener(v->{getSharedPreferences("session",MODE_PRIVATE).edit().clear().apply();startActivity(new Intent(this,LoginActivity.class));finish();});String t=getSharedPreferences("session",MODE_PRIVATE).getString("token","");welcome.setText("Mi portal");Executors.newSingleThreadExecutor().execute(()->{try{JSONArray a=api.appointments(t),n=api.notifications(t);runOnUiThread(()->render(a,n));}catch(Exception e){runOnUiThread(()->countA.setText("No fue posible cargar la información"));}});}
 void render(JSONArray a,JSONArray n){countA.setText("Citas: "+a.length());countN.setText("Avisos: "+n.length());for(int i=0;i<a.length();i++){try{JSONObject x=a.getJSONObject(i);TextView v=new TextView(this);v.setText(x.optString("date")+" · "+x.optString("time")+"\n"+x.optString("service")+"\n"+x.optString("professional"));v.setTextSize(13);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setTextColor(0xff17313B);v.setPadding(16,16,16,16);container.addView(v,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));}catch(Exception ignored){}}}
}
